// WHILE Loop (Pre-test)
int i = 0;
while (i < 10) {
    // Code block executes if condition is true
    i++;
}


// DO-WHILE Loop (Post-test, guaranteed execution)
int x = 5;
do {
    // Executes at least once
    x--;
} while (x > 0);


// FOR Loop (Controlled iteration)
int sum = 0;
for (int k = 0; k < 5; k++) {
    sum += k;
}
// Note: k scope depends on C standard (C99+ block scoped)
